/**
 * @file
 * Merges retained operations without replacing a live Projection's independent history.
 */
#include "../class.hpp"

namespace sequencer {
Result Projection::merge(std::span<const Insertion> insertions,
                         const std::vector<Acknowledgement> &frontiers) {
  Result result;
  for (const auto &insertion : insertions)
    apply(insertion, result);
  // Retained claims are observed after Acknowledgements generated by apply, matching snapshot
  // application order.
  for (const auto &a : frontiers)
    frontier.observe(a);
  return result;
}
} // namespace sequencer
